mapper.update:
update replay_session
session_name = #{sessionName}, symbol = #{symbol}, exchange_code = #{exchangeCode}, mode = #{mode}, source_type = #{sourceType}, status = #{status}, source_trace_id = #{sourceTraceId}, replay_trace_id = #{replayTraceId},
where id = #{id}

mapper.select:
select id, session_name, symbol, exchange_code, mode, source_type, status, source_trace_id, replay_trace_id
from replay_session
where id = #{id}

select id, session_id, trace_id, event_type, symbol, exchange_code, payload_json from replay_event
session_id = #{sessionId}
order by id desc
